CREATE TABLE game_deck (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text NOT NULL UNIQUE, title text NOT NULL, rounds jsonb NOT NULL, source jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_room (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pin char(6) NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES app_user(id), deck_id uuid NOT NULL REFERENCES game_deck(id), phase text NOT NULL DEFAULT 'lobby' CHECK (phase IN ('lobby','listen','comprehend','quiz','review','finished')), round_index integer NOT NULL DEFAULT 0, revision integer NOT NULL DEFAULT 0, opened_at timestamptz, deadline timestamptz, expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_player (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES game_room(id), token_hash char(64) NOT NULL UNIQUE, alias text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_answer (room_id uuid NOT NULL REFERENCES game_room(id), player_id uuid NOT NULL REFERENCES game_player(id), round_index integer NOT NULL, choice integer NOT NULL CHECK(choice BETWEEN 0 AND 3), points integer NOT NULL CHECK(points BETWEEN 0 AND 1200), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,player_id,round_index));
CREATE TABLE game_cloud (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES game_room(id), player_id uuid NOT NULL REFERENCES game_player(id), round_index integer NOT NULL, term text NOT NULL CHECK(char_length(term) BETWEEN 1 AND 40), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(room_id,player_id,round_index));
CREATE TABLE game_cloud_decision (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cloud_id uuid NOT NULL REFERENCES game_cloud(id), owner_id uuid NOT NULL REFERENCES app_user(id), visible boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX game_player_room ON game_player(room_id);
CREATE INDEX game_cloud_room ON game_cloud(room_id,round_index);
